window.HARDTRP.receive("45329",[[45330,"2026-06-14T12:44:52",9,"Начало темы.\n\n@Pro551o  Дм этой темы.\n\nЭто ответвление квеста \"Странные земли 2\" — https://t.me/c/3707373216/36850",45329,null],[45369,"2026-06-14T16:35:49",36,"Кью решила что оставаться с ними это верная гобэлла, поэтому она потратила время своего дежурства на то чтобы перерисовать и запомнить карту. Затем оставив в одежде суккуба частичку себя ввиде рассады спор, на тот случай если они попадут в беду. А после забрав волка и свои вещи покинула помещение, заранее спыздыв у волшебника или ыгра факел и поджигая его с помощью заговора уже на улице иду по карте туда куда мы все собирались изначально",45329,null],[45433,"2026-06-14T18:15:19",23,"Ну типа нету факелов...",45329,null],[45443,"2026-06-14T18:17:36",36,"У меня свячки",45433,null],[45444,"2026-06-14T18:17:47",23,"ох бля",45329,null],[45446,"2026-06-14T18:17:57",23,"мне пришлось порыться в трусах всех персонажей оказывается у орка есть шесть факелов",45329,null],[45449,"2026-06-14T18:19:01",23,"как я понимаю забираешь все факелы?",45329,null],[45455,"2026-06-14T18:21:42",23,"*перед тем как ты вышла ты замечаешь лютый и холодно улице кажется вот-вот пойдёт какбуто посередине зимы вечером прекратился но от этого не легче Ты какие твои волки начинаете потихоньку замерзать вас согревает лишь немного факел который какого-то чёрта всё ещё освещает не дальше десяти фуд яркого освещения дальше тьма*",45329,null],[45501,"2026-06-14T18:31:54",23,"Да уже иду за чаем",45329,null],[45502,"2026-06-14T18:32:45",36,"Иду дальше следуя точке на карте согревая себя открытым пламенем факела о себя, так как он мне ничего не может сделать а волка я грею уже по аккуратнее, покрывая его своей одеждой, словно одеялом",45455,null],[45503,"2026-06-14T18:34:16",23,"*ты без понятия где ты*",45329,null],[45505,"2026-06-14T18:34:56",23,"карта была магический и она могла показывать где вы А то что ты срисовала без понятия просто идёшь по примерному маршруту//",45329,null],[45584,"2026-06-14T18:51:09",23,"Ладно кинь внимательность",45329,null],[45603,"2026-06-14T18:57:46",36,"/r +5\nКью",45329,null],[45605,"2026-06-14T18:57:59",36,"/r +3\nволк",45329,null],[45607,"2026-06-14T18:58:01",23,"в целом нихуя//",45329,null],[45608,"2026-06-14T18:58:08",23,"лес Как лес//",45329,null],[45613,"2026-06-14T18:58:37",23,"Ну пусть тогда кидает мудрость от испуга",45609,null],[45615,"2026-06-14T18:58:46",36,"//спас?",45613,null],[45616,"2026-06-14T18:58:53",23,"да",45329,null],[45617,"2026-06-14T18:59:09",36,"/r +1",45329,null],[45621,"2026-06-14T19:01:08",23,"*ну ты замечаешь то что в отличие от тебя волк Ну скажем так немного постарел и дика боится чего-то и только в этот момент ты замечаешь то что уже на протяжении некоторого времени не слышишь вообще никаких звуков вокруг себя кроме волка и травы которые вы ходите при этом ты всё ещё видишь два сияющих глаза вдали который смотрел на вас с самого утра*",45329,null],[45623,"2026-06-14T19:02:52",36,"Грозно смотрю на него\n\n- ВОТ ЧТО ТЫ ОТ МЕНЯ ХОЧЕШЬ?! А?!\n\nОскалившись смотрит на сущность\n\n- Не мешай... Помоги лучше...\n\nПочему-то перешла на сильван и слегка грустно произнесла",45621,null],[45628,"2026-06-14T19:07:07",23,"д10 кинь//",45623,null],[45633,"2026-06-14T19:08:35",36,"/r d10",45628,null],[45637,"2026-06-14T19:10:00",23,"*вини свою удачу путник*\n\n*слышится шёпот повсюду пока не понимаешь то что это исходит из твоей же головы*",45329,null],[45638,"2026-06-14T19:11:04",23,"*ты слышишь дикий ор и звуки дикого зверя кажется медведь? очень свирепый очень громко орёт но весь лес в лесу Всё ещё нет никаких звуков кроме его*",45329,null],[45639,"2026-06-14T19:11:22",36,"- Я свою удачу винила последний раз когда попала в мир фей... Но оказалось что мне очень даже повезло...\n\nПодготавливает заклинание драконий удар и активирует симбиотическую сущность",45637,null],[45640,"2026-06-14T19:11:46",36,"- Мишка...",45638,null],[45651,"2026-06-14T19:13:35",23,"*ты слышишь просто как он рычит на весь лес и жадно что-то пожирает настолько громко жуёт и ломает кость своей челюстью и чавкает что его слышно практически везде из-за того что тут нет звука ещё лучше но ты не знаешь где он*\n\n\nделай что-то ещё?",45329,null],[45653,"2026-06-14T19:14:28",36,"Кью стоит на месте и прислушивается, чтобы понять что именно это за медведь, бурый? Черный? Белый? стоит ли ей с ним сталкиваться?",45651,null],[45654,"2026-06-14T19:14:42",36,"Восприятие же?",45329,null],[45656,"2026-06-14T19:15:46",23,"да//",45329,null],[45659,"2026-06-14T19:16:17",36,"/r +5",45329,null],[45661,"2026-06-14T19:16:24",36,"//м...",45660,null],[45662,"2026-06-14T19:16:26",36,"//ОК",45329,null],[45663,"2026-06-14T19:16:42",23,"*ты быстро замечаешь то что вокруг вас огромные деревья и твой волчок Ну немного ходят по болоту Ну начинает ходить немного грязь ещё немного и там будет полностью только вода*",45329,null],[45666,"2026-06-14T19:17:02",23,"Ну типа вода по колено//",45329,null],[45668,"2026-06-14T19:17:12",23,"теперь пожалуй инициатива//",45329,null],[45673,"2026-06-14T19:17:55",36,"//так мы на месте стояли...",45663,null],[45676,"2026-06-14T19:19:17",23,"Ну ты только это и заметила//",45329,null],[45679,"2026-06-14T19:20:09",36,"/r +2\nВолк",45329,null],[45682,"2026-06-14T19:20:26",36,"/r +2",45329,null],[45684,"2026-06-14T19:20:31",36,"Кью",45683,null],[45692,"2026-06-14T19:22:04",23,"/roll d20+1",45329,null],[45714,"2026-06-14T19:28:09",36,"Я вижу как это на меня бежит?\nУ меня типо ход есть чтобы подготовиться или как?",45698,null],[45715,"2026-06-14T19:30:55",23,"*не успела пройти или несколько минут как это существо к вам подбежало сзади где-нибудь полностью окровавленное оставляя за собой какой-то след крови и быстро ты понимаешь это оборотень.... тот грозно выходит перед тобой и пытается атаковать*",45329,null],[45716,"2026-06-14T19:31:04",23,"Да ты до этого подготавливала действие если что Но можешь прямо сейчас сделать//",45714,null],[45717,"2026-06-14T19:32:09",36,"//а это в основном атакующие заклинания что требуют подготовки, так что пусть атакует",45716,null],[45719,"2026-06-14T19:32:30",36,"//но тогда я не реакцию а бонус трачу",45329,null],[45720,"2026-06-14T19:32:33",36,"//это плюс",45329,null],[45723,"2026-06-14T19:33:28",23,"/roll d20+6",45329,null],[45725,"2026-06-14T19:33:34",23,"попал?",45329,null],[45726,"2026-06-14T19:34:16",36,"Ну... Есть чут чут такого",45725,null],[45727,"2026-06-14T19:34:34",23,"/roll d8+4",45329,null],[45729,"2026-06-14T19:34:41",23,"режущего урона//",45329,null],[45731,"2026-06-14T19:35:14",36,"//нарративно от меня усилился запах грибов а вокруг меня было заметно белое облоко спор. На посохе же появилась голова серебряного дракона",45716,null],[45732,"2026-06-14T19:35:18",23,"*огромный массивные лапы он просто пытается схватить и полностью вырывает одну из ветвь торчащий с тебя*",45715,null],[45733,"2026-06-14T19:36:01",23,"это конец его хода одна атака//",45329,null],[45734,"2026-06-14T19:36:15",36,"//угу... Фулл за на месте",45728,null],[45735,"2026-06-14T19:36:55",36,"//пусть кинет спас тела",45733,null],[45736,"2026-06-14T19:38:05",23,"/roll d20+6",45329,null],[45738,"2026-06-14T19:38:12",23,"....",45329,null],[45741,"2026-06-14T19:41:55",36,"//не прошёл! Прошел....",45738,null],[45742,"2026-06-14T19:43:24",23,"*просто замечаешь то что это неповоротливая скотина*",45329,null],[45745,"2026-06-14T19:44:17",36,"Кью сжимает свой посох в руках и с недовольством смотрит на оборотня\n\n - Плохой пёсик!\n\nОна замахивается посохом и тот начинает светиться (заговор: дубинка), а после со всей силы бьёт по морде оборотня посохом целясь наконечником посоха",45329,null],[45758,"2026-06-14T19:50:10",36,"//атаковать?",45329,null],[45759,"2026-06-14T19:50:20",23,"Ну в целом как хочешь да//",45329,null],[45760,"2026-06-14T19:50:52",23,"на попадание//",45329,null],[45761,"2026-06-14T19:50:58",23,"сори меня тут просто отвлекли//",45329,null],[45762,"2026-06-14T19:52:14",36,"/r +6",45329,null],[45764,"2026-06-14T19:52:20",36,"//попала",45763,null],[45765,"2026-06-14T19:53:44",23,"да",45329,null],[45766,"2026-06-14T19:53:45",36,"/r d8+3+d6+d6",45329,null],[45768,"2026-06-14T19:53:54",23,"напомни откуда весь урон//",45329,null],[45769,"2026-06-14T19:54:07",23,"1д8 знаю плюс модификатор//",45329,null],[45770,"2026-06-14T19:54:17",23,"ещё один - Это драконья вроде//",45329,null],[45771,"2026-06-14T19:54:37",36,"//и ещё симбиотическая сущность",45770,null],[45772,"2026-06-14T19:55:03",36,"Ваши рукопашные атаки оружием наносят дополнительные 1к6 урона некротической энергией любой цели, по которой они попадают.",45329,null],[45773,"2026-06-14T19:55:06",23,"окей //",45329,null],[45774,"2026-06-14T19:55:28",23,"*Ты замечаешь то что он до этого тоже был ранен после твоей атаки он начинает скулить но всё ещё не отступает*",45329,null],[45776,"2026-06-14T19:57:12",23,"*он весь в крови из его пасти обильно льёт слюна что даже от рыка попадает тебе на лицо и за ним идёт кровавая полоса не только его но и чья-то только что плотно поел но всё ещё голоден видимо*",45329,null],[45778,"2026-06-14T19:57:31",23,"Ну теперь ходи хоть за волка//",45772,null],[45798,"2026-06-14T20:05:41",36,"//ах да...",45778,null],[45804,"2026-06-14T20:06:57",36,"Волк видит как его хозяйка получает удар от грозного волкообразного перед ним и принимает грозное решение напасть на врага, он с рыком расскрывает свою пасть и вонзается в ногу оборотня своими острыми зубами отрывая от негу куски плоти",45329,null],[45805,"2026-06-14T20:07:04",36,"/r +d20+4",45329,null],[45807,"2026-06-14T20:07:26",36,"/r 2d4+2",45329,null],[45811,"2026-06-14T20:07:46",23,"спас силой как понимаю?//",45329,null],[45813,"2026-06-14T20:08:42",23,"*творя не оценила такого прикола и просто остановил волка лапой ему хоть и прокусили лапу ему хоть бы хны он даже немного посмеивается*",45329,null],[45814,"2026-06-14T20:08:51",36,"//да",45811,null],[45815,"2026-06-14T20:09:02",23,"/roll d20+6",45329,null],[45817,"2026-06-14T20:09:18",23,"описывай как ты делаешь от такого положения//",45813,null],[45820,"2026-06-14T20:10:38",36,"Волк с большой силой тянет ногу оборотня на себя, да так сильно что оборотень теряет равновесие и падает на спину, а волк отрывает кусок свежей плоти, а после отбрасывает её в сторону злобно рыча и глядя на противника",45816,null],[45822,"2026-06-14T20:11:44",36,"//норм?",45820,null],[45834,"2026-06-14T20:14:24",23,"пойдёт//",45329,null],[45835,"2026-06-14T20:14:32",23,"в общем Во сколько ХП волк//",45329,null],[45840,"2026-06-14T20:15:17",23,"*он орёт в ответ*",45820,null],[45842,"2026-06-14T20:15:24",23,"ты всё ещё сидишь на волке?//",45822,null],[45843,"2026-06-14T20:15:27",36,"//мала, 11",45835,null],[45845,"2026-06-14T20:15:30",36,"//дя",45842,null],[45846,"2026-06-14T20:15:41",36,"//ну или...",45843,null],[45847,"2026-06-14T20:15:50",36,"/r 2d8+2",45329,null],[45849,"2026-06-14T20:15:53",36,"//12",45848,null],[45850,"2026-06-14T20:16:17",23,"*он встаёт и сразу хватает волка за лапу А чего ты выпадаешь на землю он поднимает волка вверх над своей головой и готовиться либо порвать его пополам либо сожрать*",45329,null],[45852,"2026-06-14T20:16:33",23,"/roll d4+4",45329,null],[45856,"2026-06-14T20:16:53",23,"*волк явно больно от того что его взяли и сейчас порвут напополам если ничего не сделать*",45853,null],[45862,"2026-06-14T20:17:14",23,"/roll d20+6",45329,null],[45869,"2026-06-14T20:17:55",23,"кинь монетку?",45329,null],[45870,"2026-06-14T20:18:05",36,"//1 или 2?",45329,null],[45872,"2026-06-14T20:18:11",23,"1",45329,null],[45873,"2026-06-14T20:18:13",36,"/r d2",45329,null],[45876,"2026-06-14T20:18:26",36,"//он выбирается",45329,null],[45878,"2026-06-14T20:18:42",23,"*волку удаётся избежать захвата Ну ты всё равно выпадаешь на этом ход твари закончен*",45329,null],[45880,"2026-06-14T20:18:58",23,"*злобный орёт то что ему не удалось схватить за лапу того кто его укусил*",45329,null],[45888,"2026-06-14T20:22:16",36,"- АХ ТЫ ТВАРЬ!\n\nКричит Кью, а после подбегает к оборотню, замахивается (заговор дубинка) и бьёт оборотня прямо меж ног\n\n- За Вульфи! ПЛОХАЯ СОБАКА!",45878,null],[45889,"2026-06-14T20:22:29",36,"//кинь кста за тот ход спас тела",45878,null],[45902,"2026-06-14T20:27:43",23,"/r 1d20+6",45329,null],[45904,"2026-06-14T20:28:02",23,"от чего?//",45889,null],[45905,"2026-06-14T20:28:02",36,"//провал",45903,null],[45909,"2026-06-14T20:28:53",36,"облако споров что витало вокруг Кью наконец смогло проникнуть под кожу оборотня, принося ему дискомфорт и ужасные ощущения",45904,null],[45912,"2026-06-14T20:29:22",36,"/r d4+d4",45329,null],[45918,"2026-06-14T20:29:47",36,"//это на что?",45329,null],[45919,"2026-06-14T20:29:49",23,"/roll -d20+6",45329,null],[45923,"2026-06-14T20:30:35",23,"*у него начинают гореть глаза от этого он невероятно когтистой лапы чешет своё лицо что царапает своё лицо и немного свой глаз и после очень жёстко промахивается и ударяется головой об ствол соседнего дерева*",45329,null],[45927,"2026-06-14T20:30:41",23,"на этом всё//",45329,null],[45930,"2026-06-14T20:31:41",36,"//урон?",45923,null],[45931,"2026-06-14T20:31:48",36,"//или типо эт норма?",45329,null],[45997,"2026-06-14T20:49:49",23,"Ну типа он свой ход проебланил ещё и удалился в места атаки//",45329,null],[45999,"2026-06-14T20:50:20",23,"~разочаровывающе не так ли?\n*снова голос в голове*",45329,null],[46005,"2026-06-14T20:51:25",36,"- Да... Слаб... \n\nГоворит Кью которая даже не пострадала толком, что не скажешь про волка",45999,null],[46010,"2026-06-14T20:51:38",36,"//я вижу его? или он отступил? просто добить хочу",45997,null],[46011,"2026-06-14T20:51:50",23,"оборотень всё ещё стоит перед тобой//",46010,null],[46013,"2026-06-14T20:51:57",23,"Я просто описывал как он промахнулся твой ход всё ещё//",45329,null],[46022,"2026-06-14T20:53:49",36,"//ААААА",46013,null],[46025,"2026-06-14T20:54:21",23,"~забавно раньше я слышал другое развеять тебе скуку? \n\n*просто слышишь рычание со всех сторон*\n\n~Хотя ладно но сообщи потом\n\n*после чего всё снова утихает но ты видишь неисчислимое количество глаз светящийся во тьме смотрящий на тебя*",46005,null],[46032,"2026-06-14T20:55:44",36,"- Ну ничего... Я ЗАКОНЧУ ЕГО МУКИ!!!\n\nГлаза Кью бешено закрутились в круговороте красок, руки покрылись кроваво красными красками, а сама Кью злобно улыбнулась словно ей это нравилось, а после она замахнувшись Посохом (заговор дубинка) Ударила со всей силы по бедному оборотню раскрашивая его жалкую черепушку",46011,null],[46034,"2026-06-14T20:55:50",36,"/r +6",45329,null],[46038,"2026-06-14T20:55:55",36,"//бля...",46035,null],[46043,"2026-06-14T20:56:18",23,"*существо просто лапой держит твою дубинку*",45329,null],[46048,"2026-06-14T20:56:50",23,"теперь действия с твоей собачки//",45329,null],[46052,"2026-06-14T20:57:23",23,"~какая досада \n*просто небольшой усмешливый комментарий*",45329,null],[46055,"2026-06-14T20:57:50",36,"Вульфи просто с разбегу вгрызается в глотку оборотня",45329,null],[46056,"2026-06-14T20:57:58",36,"/r +d20+4",45329,null],[46061,"2026-06-14T20:58:09",23,"не попал//",45329,null],[46065,"2026-06-14T20:58:23",36,"//как вовремя рак кубов...",46057,null],[46068,"2026-06-14T20:59:18",23,"*он вгрызается но не может прокусить плотный мех *",45329,null],[46073,"2026-06-14T21:00:20",23,"*существо совсем удовольствием снимает себя волка и использует его как метательное оружие///",45329,null],[46075,"2026-06-14T21:00:33",23,"/roll d20+6",45329,null],[46077,"2026-06-14T21:00:42",23,"а прошу проверку атлетики волка//",45329,null],[46090,"2026-06-14T21:04:33",36,"//Думаю пизда волку",46077,null],[46091,"2026-06-14T21:04:38",36,"/r +1",45329,null],[46093,"2026-06-14T21:04:39",23,"да//",45329,null],[46094,"2026-06-14T21:04:43",36,"//мдэээ",46092,null],[46096,"2026-06-14T21:04:59",23,"волк улетает как мячик для бейсбола//",45329,null],[46098,"2026-06-14T21:05:07",23,"в следующем будешь ты конец хода//",45329,null],[46099,"2026-06-14T21:05:25",23,"~кажется накаркала? \n*все тот же голос*",45329,null],[46123,"2026-06-14T21:13:27",36,"//сколько урона по нему?",46096,null],[46124,"2026-06-14T21:13:48",36,"- Заткнись... Просто осечка...\n\n//пусть кинет спас тела",46099,null],[46125,"2026-06-14T21:13:52",23,"/r 8d6",45329,null],[46127,"2026-06-14T21:13:57",36,"//....",46126,null],[46129,"2026-06-14T21:14:06",23,"Ну урон от падения....//",45329,null],[46131,"2026-06-14T21:14:28",23,"~ну да ну да \n*голосок*",46124,null],[46132,"2026-06-14T21:14:35",23,"/r d20+6",45329,null],[46134,"2026-06-14T21:14:41",36,"//это шо?",46132,null],[46135,"2026-06-14T21:14:57",23,"спас тела",45329,null],[46136,"2026-06-14T21:15:01",36,"//какой ход оборотня по счёту? 4?",46133,null],[46137,"2026-06-14T21:15:04",23,"на этом ход всё Если что можешь ходить//",45329,null],[46145,"2026-06-14T21:15:39",23,"Ну типа он свой ход сделал действие захват И кинул волка/)",45329,null],[46146,"2026-06-14T21:15:46",23,"теперь твой ход//",45329,null],[46149,"2026-06-14T21:16:14",36,"//Я говорю сколько ВСЕГО он сделал ходов",46145,null],[46150,"2026-06-14T21:16:45",23,"3 вроде",45329,null],[46156,"2026-06-14T21:17:08",36,"//Я просто вечно забываю просить тебя кинуть спасы тела, хотя споры просто всегда ебашут врага на постоянке, так что когда ходить будешь, кидай ПЖ ещё и спас тела",45329,null],[46159,"2026-06-14T21:18:02",23,"критическая хуиня//",45329,null],[46160,"2026-06-14T21:18:49",36,"Посмотрела вслед за улетающим Вульфи\n\n- ТВАРЪ\n\nКью крепко сжала посох и тот стал святится ало-красным (заговор дубинка)\n\n- Я тебя по стенке размажу!\n\nОна замахнулась посохом словно Битой и со всей дури ебанула оборотню в челюсть\n\n//кста, как далеко от меня волк?",46126,null],[46161,"2026-06-14T21:19:03",36,"//удвоенный урон?",46159,null],[46162,"2026-06-14T21:19:11",23,"ага//",46161,null],[46163,"2026-06-14T21:19:12",36,"/r 2d4+d4",46158,null],[46167,"2026-06-14T21:19:46",36,"@Pro551o",46160,null],[46169,"2026-06-14T21:20:08",36,"/r +6\nНа попадание, если не попадёт то я вешаюсь",45329,null],[46171,"2026-06-14T21:20:11",23,"Ты видишь только на 10 фуд а он улетел далеко за это//",46160,null],[46173,"2026-06-14T21:20:22",36,"//пизда...",46171,null],[46175,"2026-06-14T21:20:59",23,"~мои руки на столе я ничего не делал))\n*тот же голос*",45329,null],[46180,"2026-06-14T21:22:07",23,"*Вервольф начинает хочется от невыносимой боли отпор что начинают буквально пожирать его лицо и глаза почти полностью*",45329,null],[46181,"2026-06-14T21:22:14",23,"/roll d20+6",45329,null],[46187,"2026-06-14T21:22:40",23,"*постоянно чихает и чуть ли не умирает от такого прикрыв лапы лицо пытается убежать*",45329,null],[46191,"2026-06-14T21:23:19",36,"//За этот ход ты заранее кинул спас? или ещё раз?)",46187,null],[46192,"2026-06-14T21:23:28",23,"заранее//",46191,null],[46193,"2026-06-14T21:23:36",36,"//ок",46192,null],[46194,"2026-06-14T21:23:50",23,"можешь сделать спровоцированную атаку//",46187,null],[46200,"2026-06-14T21:24:44",36,"- СТОЙ ТВАРЬ!\n\nРванула за ним, но перед этим ещё раз ебанула по оборотню головой дракона, что была на посохе прямо ему в морду",46187,null],[46201,"2026-06-14T21:24:49",36,"/r +6",45329,null],[46203,"2026-06-14T21:24:56",36,"//3 раз...",46202,null],[46204,"2026-06-14T21:25:04",36,"//это пиздэц...",45329,null],[46207,"2026-06-14T21:25:18",23,"*атак достаёт но после застревает в его спине*",45329,null],[46210,"2026-06-14T21:25:47",23,"*Он практически ослеп от твоих споры и просто понюхал бежит на кровь которую до этого был измазан куда-то в лес*",45329,null],[46212,"2026-06-14T21:25:52",23,"ты держишься за посох?//",46207,null],[46216,"2026-06-14T21:26:39",36,"//угу, а зажённый факел воткнут в мою спину",46212,null],[46217,"2026-06-14T21:26:45",36,"/r +2",45329,null],[46220,"2026-06-14T21:26:55",36,"//огонь с факела перешёл на меня",45329,null],[46221,"2026-06-14T21:27:00",36,"//Кью горит",45329,null],[46222,"2026-06-14T21:27:05",36,"// :3",45329,null],[46224,"2026-06-14T21:27:10",23,"легенда//",45329,null],[46225,"2026-06-14T21:27:24",23,"выбери больше или меньше",45329,null],[46226,"2026-06-14T21:27:27",36,"//ей то похуй на огонь\nон магический",46224,null],[46227,"2026-06-14T21:27:29",23,"вы сейчас в облаке спор",45329,null],[46228,"2026-06-14T21:27:37",36,"//а вот волку нет",45329,null],[46233,"2026-06-14T21:28:14",36,"//перечитай заговор сотворение пламени",45329,null],[46238,"2026-06-14T21:28:59",23,"огонь начинает урон наносить тебе тоже когда используется для атаки //",45329,null],[46241,"2026-06-14T21:29:26",36,"//ну так он был зажён не для атаки",46238,null],[46242,"2026-06-14T21:29:29",36,"//так что....",45329,null],[46244,"2026-06-14T21:29:35",36,"//это если ты его метаешь",45329,null],[46246,"2026-06-14T21:29:41",36,"//а если он как пламя?",45329,null],[46248,"2026-06-14T21:29:59",23,"ты не выбираешь то что наносит он или нет//",45329,null],[46251,"2026-06-14T21:30:05",23,"Просто поклонов у тебя в руке он не наносит//",45329,null],[46259,"2026-06-14T21:31:05",36,"//ну ладна....\nпросто сказано что мне он не вредит, а ругим ХЫЗЫ",45329,null],[46262,"2026-06-14T21:31:24",23,"Ну да нечёткие формулировки убивают//",45329,null],[46264,"2026-06-14T21:31:52",23,"Ну вы оба получаете урон потому что вы впритык находитесь ты у него на спине горишь//",45329,null],[46266,"2026-06-14T21:32:14",23,"/roll d20+6",45329,null],[46268,"2026-06-14T21:32:21",23,".",46225,null],[46277,"2026-06-14T21:35:02",36,"//ну давай меньше",46268,null],[46278,"2026-06-14T21:35:15",23,"Ктулху значит",45329,null],[46279,"2026-06-14T21:35:23",23,"/r d100",45329,null],[46281,"2026-06-14T21:35:30",23,"вы не взрывайтесь//",45329,null],[46284,"2026-06-14T21:36:25",23,"Ну понимаешь там более споры грибов и не только твои//",45329,null],[46285,"2026-06-14T21:36:37",36,"//СПАСИБО БЛЯ",46281,null],[46286,"2026-06-14T21:36:37",36,"//мой ход?",45329,null],[46288,"2026-06-14T21:36:56",23,"*существо добегает до трупа единорога и начинает жадно пожирать его до конца чтобы отхилиться*",45329,null],[46289,"2026-06-14T21:37:00",23,"Вот теперь да//",45329,null],[46296,"2026-06-14T21:40:13",36,"- НЕ СМЕТЬ!\n\nКью закрепилась на его теле с помощью ног, а после засунула голову дракона в светящуюся пасть оборотня оттягивая его голову от тела единорога\n\n- НЕ СМЕТЬ!!!",46288,null],[46297,"2026-06-14T21:40:20",36,"/r +6",45329,null],[46300,"2026-06-14T21:40:26",36,"//ДА ДЕТКА!",46298,null],[46302,"2026-06-14T21:40:40",36,"/r d8+3+d6+d6",45329,null],[46305,"2026-06-14T21:40:44",36,"//бля...",46303,null],[46307,"2026-06-14T21:41:02",23,"*это полностью рвёт пасть оборотню*",45329,null],[46309,"2026-06-14T21:41:24",23,"он на последнем издыхании//",45329,null],[46315,"2026-06-14T21:42:18",23,"*голова дракона появляется внутри пасти оборотня от чего рвёт её пополам её челюсть выпадает вниз выглядит ужасно и от неё обильно льётся кровь*",45329,null],[46317,"2026-06-14T21:42:33",23,"/roll d20+6",45329,null],[46328,"2026-06-14T21:43:30",23,"*споры окончательно добивают его глаза в отчайной попытке он пытается достать тебя лапой но не может натянуться потому что ты у него на спине*",45329,null],[46333,"2026-06-14T21:44:21",23,"*в итоге оборотень в отчаянии просто лежит на земле порватой пастью (без нижней челюсти) практически ослеплены спорами и весь в ранах лежит кровоточит оперевшись на одну лапу не может достать тебя второй*",45329,null],[46334,"2026-06-14T21:44:25",23,"конец хода",45329,null],[46341,"2026-06-14T21:46:23",36,"//мой ход?",46333,null],[46342,"2026-06-14T21:46:36",36,"//спас он провалил?",45329,null],[46343,"2026-06-14T21:46:42",23,"да//",46342,null],[46344,"2026-06-14T21:46:51",36,"/r d4+d4",45329,null],[46348,"2026-06-14T21:47:50",23,".",46328,null],[46350,"2026-06-14T21:47:58",36,"- Умри грязное животное....\n\nКью вытаскивает из его пасти посох а затем вонзает ему его прямо в шею  перекрывая доступ к кислороду и ломая ему шею",45329,null],[46351,"2026-06-14T21:48:02",36,"/r +6",45329,null],[46353,"2026-06-14T21:48:14",23,"добивай его",45329,null],[46354,"2026-06-14T21:48:15",36,"/r d8+3+d6+d6",46352,null],[46363,"2026-06-14T21:53:07",36,"Посох пробивает его шею выпуская кучу крови наружу от чего она перемешивается с кровью единорога, а мертвое тело падает на землю.\n\nКью медленно вытаскивает посох из тела оборотня и пальцем проводит по окровавленному концу, после чего слизывает кровь с пальца\n\n- Не хватает чего-то...\n\nГоворит вся с ног до головы укрытая кровью оборотня Кью\n\n- Знаю....\n\nОна переворачивает оборотня на спину  и вонзает свою руку в его дырявое горло. А после опускает голову к его уху\n\n- Ты будешь жить, тварь...\n\nОна выпустила облако спор из руки прямо в тело оборотня от чего тот надулся, затем она вытащила из него свою руку и вправила ему челюсть перевязав её подручными средствами\n\n- Ну что же... Пошли...\n\nОна потащила тело оборотня за собой",46355,null],[46365,"2026-06-14T21:54:34",23,"~охохо жестокпя дивица \n*просто радостный голосок*",45329,null],[46366,"2026-06-14T21:55:42",23,"не понял что ты сделала....//",46363,null],[46367,"2026-06-14T21:56:05",36,"- Спасиба, рада что вам понравилось...\n\nПосмотрела на единарога, а после на обротня\n\n- Ну не бросать же провизию...\n\nОна бросила тело оборотня и пошла жрать внутренности единорога",46365,null],[46374,"2026-06-14T21:57:39",23,"спас интеллекта",46367,null],[46377,"2026-06-14T21:58:04",36,"/r +2",46374,null],[46381,"2026-06-14T21:58:36",23,"*твои споры поглощаются телом хоть даже мёртвых существо явно магическое и полностью игнорирует эти споры почему-то хотя до этого умирали от них*",46363,null],[46384,"2026-06-14T21:59:04",23,"ты считаешь не самые лучшие идея кушать магическое существо//",46378,null],[46386,"2026-06-14T22:00:07",36,"Покушав Кью вытерла кровь единорога с губ и выпрямившис собиралась взять оборотня и потащить его с собой как заметила что споры пропали а тело оборотня не испускает сингулярность флоренов, тогда она со злости пнула его в морду и обижена надувшись пошла прямо, она подожгла свою руку так как факел сгорел.",46367,null],[46387,"2026-06-14T22:00:10",36,"//а....",46384,null],[46388,"2026-06-14T22:00:13",36,"//почему что угодно но не то что мне нужно...",45329,null],[46389,"2026-06-14T22:00:40",23,"Ладно кинь четыре раза На харизму",45329,null],[46390,"2026-06-14T22:00:50",23,"Спас",45329,null],[46391,"2026-06-14T22:01:32",36,"/r \n/r \n/r \n/r",45329,null],[46396,"2026-06-14T22:01:48",23,"пизда",45329,null],[46397,"2026-06-14T22:02:00",36,"|/пизда",45329,null],[46398,"2026-06-14T22:02:45",23,"/roll d4-1\n/roll d4-1\n/roll d4-1\n/roll d4-1",45329,null],[46400,"2026-06-14T22:02:58",23,"упали характеристики",45329,null],[46402,"2026-06-14T22:03:04",36,"....",46400,null],[46403,"2026-06-14T22:03:07",36,"//на долго?",45329,null],[46404,"2026-06-14T22:03:15",23,"никто не знает//",45329,null],[46406,"2026-06-14T22:03:44",36,"//не не, ты мне скажи, я и так из за системы закупа на дне в харах, так ты мне ещё и так их понизел",46404,null],[46408,"2026-06-14T22:04:26",23,"*после того как выпрямлялась чувствуешь Как сразу исказилась пространство начало мутнеть  потом тебя вырвало и чувствуешь истощения в своих сил*",46386,null],[46410,"2026-06-14T22:04:55",23,"пока их не снимешь Ну сейчас скажу",46406,null],[46411,"2026-06-14T22:05:12",23,"/roll d6+1 длинных отдыхов",45329,null],[46413,"2026-06-14T22:05:17",23,"три длинных отдыха",45329,null],[46417,"2026-06-14T22:07:02",23,"сама распределишь какие характеристики как понизились//",46399,null],[46418,"2026-06-14T22:07:08",36,"//уже приемлема\nа что именно понизилось",45329,null],[46419,"2026-06-14T22:07:13",36,"/АААА\nНАСТОЛЬКО",46417,null],[46420,"2026-06-14T22:07:29",23,"У тебя понизу есть именно характеристики",45329,null],[46421,"2026-06-14T22:07:33",36,"Сила",46399,null],[46423,"2026-06-14T22:07:41",36,"харизма",46399,null],[46425,"2026-06-14T22:07:48",23,"ну всё сила 5",45329,null],[46426,"2026-06-14T22:07:55",36,"Интеллект",46399,null],[46427,"2026-06-14T22:08:04",36,"тело",46399,null],[46429,"2026-06-14T22:08:09",23,"пока что напиши у себя в статусе",45329,null],[46430,"2026-06-14T22:08:12",36,"мудрость",46427,null],[46434,"2026-06-14T22:08:24",36,"лучше мудрость",46430,null],[46440,"2026-06-14T22:10:04",23,"*магическое истощение*\nу вас понизились все характеристики из-за губительного эффекта магическим воздействиям \n\nполучайте -3 характеристикам силы и харизмы \n-2 интеллекта и\n-1 мудрости",45329,null],[46443,"2026-06-14T22:10:21",23,"~это было пожалуй самое наихудшее решение что ты могла принять\n*голос*",45329,null],[46456,"2026-06-14T22:12:08",36,"- А мне то откуда было знать... Когда поняла поздно было... Кстати, а ты кто? А то говоришь со мной а на связь не выходишь...\n\nУшки кью стали слегка колыхаться, от чего она меня направление своего движения (умение: ЗОВ)",46443,null],[46460,"2026-06-14T22:12:40",23,"~не обязательно знать чтобы поступить самый тупые поступки явно не пожрать магическое существо \n*просто усмехается*",46456,null],[46465,"2026-06-14T22:13:11",36,"/r +1",45329,null],[46469,"2026-06-14T22:13:22",36,"//да, волку плохо но он ещё жив",46466,null],[46532,"2026-06-14T22:20:33",23,"Ну как-то насрать на лор //",45329,null],[46535,"2026-06-14T22:20:35",36,"//ах да... хм....\nнада подумать что отправить пёсику.....",45329,null],[46538,"2026-06-14T22:20:47",23,"только вы всё ещё хз где вы//",45329,null],[46540,"2026-06-14T22:20:53",23,"пёсик жив что дальше найдите друг друга//",45329,null],[46541,"2026-06-14T22:21:25",23,"~дитя лесов какая же противная раса \n*просто между делом слышишь голос в голове*",45329,null],[46543,"2026-06-14T22:22:41",36,"//тут запахи есть?",46540,null],[46544,"2026-06-14T22:22:51",23,"Да воняет болотами//",45329,null],[46545,"2026-06-14T22:23:01",36,"//а ветер?",46544,null],[46546,"2026-06-14T22:23:08",36,"//он есть?",45329,null],[46547,"2026-06-14T22:23:08",23,"отсутствует я уже говорил//",45329,null],[46548,"2026-06-14T22:23:13",36,"//угу...",46547,null],[46549,"2026-06-14T22:23:28",36,"//как много болот вокруге? Ну по запаху?",45329,null],[46552,"2026-06-14T22:23:54",23,"Монстр натащил тебя хуй знает куда повсюду огромные деревья И повсюду болото//",45329,null],[46589,"2026-06-14T22:27:44",23,"после этого слова кинь проверка мудрости и анализа\\\\",46541,null],[46590,"2026-06-14T22:27:49",23,"каждая проверка отдельно//",45329,null],[46596,"2026-06-14T22:29:35",36,"/r +3",46541,null],[46598,"2026-06-14T22:29:59",23,"*тебе пиздец как кажется что все деревья за тобой смотрят*",46596,null],[46599,"2026-06-14T22:30:07",36,"/r -1",45329,null],[46601,"2026-06-14T22:30:14",36,"//мдэ...",45329,null],[46603,"2026-06-14T22:30:49",23,"*они готовы в любую секунду тебя порвать и тебе кажется то что среди тьмы то-то ходит помимо тех пары глаз*",46600,null],[46610,"2026-06-14T22:32:16",36,"От данного факта Кью замедлилась и сглотнула, аккуратно огиная деревья, но вскоре она остановилась и решив побороть страх из-за жизни пёсика подошла к дереву и на друидическом спросила\n\n- НЕ УБИВАЙ МЕНЯ БОЛЬШОЕ ДЕРЕВО! ПРОСТО СКАЖИ ГДЕ МОЙ ДРУГ И СЕМЬЯ....",46603,null],[46614,"2026-06-14T22:33:03",23,"*первое что она видит когда подходит к дереву это человеческое лицо покрытой корой*",45329,null],[46619,"2026-06-14T22:33:51",36,"Она это делала с закрытыми глазами",46614,null],[46620,"2026-06-14T22:34:03",23,"типа такая картина на каждом дереве",45329,null],[46621,"2026-06-14T22:34:04",36,"из за страха сожмурилась",46619,null],[46623,"2026-06-14T22:35:06",23,"*ничего не происходит Просто голос который до этого говорил*\n\n~не пойму я вас дети лесов готовы творить зверства и боитесь что может сделать с вами",46610,null],[46630,"2026-06-14T22:37:21",23,"примерно такой голос//",45329,null],[46632,"2026-06-14T22:37:29",23,"просто как будто читаешь книгу//",45329,null],[46635,"2026-06-14T22:37:59",23,"вам не обязательно Это слушать просто примерно такой голос//",45329,null],[46637,"2026-06-14T22:38:59",36,"Кью отвернулась и пошла дальше прямо думая что спросить у Вульфи\n\n- Слушай... Почему множественное лицо? Я не чувствую своих собратьев, лишь Вульфи и... Я....\n\nС неким одиночеством сказала она и села на землю а после легла и сжалась в клачок держа в руках огонёк\n\n- Вульфи потерялся... А он единственное что осталось...",46623,null],[46640,"2026-06-14T22:39:58",23,"*безжизненный без звука и тьма и вода для колена только звук воды*",45329,null],[46642,"2026-06-14T22:40:39",36,"- ТЫ ДОСТАЛА МЕНЯ! ПОЧЕМУ КОГДА НАДО ТЫ МОЛЧИШЬ! А КОГДА НЕТ БОЛТАЕШЬ! НЕНАВИЖУ!",46640,null],[46643,"2026-06-14T22:40:41",23,"~решила просто игнорировать меня дитя лисов?\n*всё ещё звук который исходят рядом с тобой но никого не видишь*",46623,null],[46648,"2026-06-14T22:41:18",23,"~а когда же надо ?",46642,null],[46651,"2026-06-14T22:41:52",36,"- Когда прошу?",46648,null],[46653,"2026-06-14T22:42:04",23,"*вечная тишина и тьма давит на голову*\n\n*пёс передаёт то что в полной темноте в холоде и в воде не понимает где он*",45329,null],[46654,"2026-06-14T22:42:05",36,"Сквозь слезы сказала Кью",45329,null],[46659,"2026-06-14T22:43:35",23,"~так позови же меня дитя достойное моего благословения \n\n~Не плачь дитя лесов только не в моих владениях \n*ты видишь то что твой свет начал светить нормально то есть на 10 фуд ярко и на 10 футов светло*",46651,null],[46662,"2026-06-14T22:44:04",23,"можешь кинуть на внимательность\\\\",45329,null],[46663,"2026-06-14T22:44:11",23,"потом ещё раз внимательность и анализ//",45329,null],[46665,"2026-06-14T22:44:27",36,"/r +5",46662,null],[46667,"2026-06-14T22:44:38",36,"||gbplffosknklgnskndpfkpkdfksdfk",46666,null],[46669,"2026-06-14T22:44:47",36,"/r +5",46663,null],[46673,"2026-06-14T22:44:56",36,"/r -1",45329,null],[46675,"2026-06-14T22:45:03",36,"//........",46674,null],[46676,"2026-06-14T22:45:08",36,"НУ КОНЕЧНО",45329,null],[46684,"2026-06-14T22:45:57",23,"*лиш сейчас в момент бесконечной кишения И одиночества видишь скромную улыбку Луны направленный прямо на тебя почему то это успокаивает.. морда безусловно жуткая но не угрожающие*",46666,null],[46686,"2026-06-14T22:46:38",36,"//Кью обкурилась",46684,null],[46687,"2026-06-14T22:46:44",36,"//Вызывайте врачей",45329,null],[46691,"2026-06-14T22:47:06",36,"//белая кровь единорога всегда была вредной, ещё из Гарри Поттера знала, но не настолько же",45329,null],[46699,"2026-06-14T22:48:09",23,"*в лесу Ты замечаешь всё больше и больше жуткостей то что ты ходишь буквально по трубу каждая труп покрыт растительностью и из трупа вырастают растения некоторые тела всё ещё живы и жадно всосались в лианы растения и пьют какую-то зелёную жижу полностью счастливые голые они срут из-за таких навоза поднимается растения жуткая картина*\n\n*потом ты разбиваешь мысли понимаешь что это всё кошмары Но люди остаются ты всё ещё видишь в некоторых людей беззаботно лежащих голыми и пьющими что-то из лиан и гадать не надо они счастливые лежат бесконечном сне бесконечные сытые *",46670,null],[46702,"2026-06-14T22:49:25",23,"~дитя лисов хочешь ли ты выйти из бесконечного кошмара? осветить мрак тьмы и перестать быть одиноки?",45329,null],[46703,"2026-06-14T22:49:42",23,"~не быть всеми этими людьми не быть во тьме не быть в холоде",45329,null],[46716,"2026-06-14T22:51:21",36,"Глядя на всё это у Кью падали руки всё сильнее, но услышав голос, о спасении о надежде, о капельки шанса на спасения отсюда Кью собралась с мыслями и взяла себя в руки\n\n- Что... Что требуется взамен?",45329,null],[46728,"2026-06-14T22:54:14",23,"*тебе кажется как будто Луна ещё больше расплылась в улыбке*\n\n~закрой глаза и посчитай до трёх \nповерь в чудо\nвот моё требование и назови моё имя\n\n\n (подсказка ты слышала В самом начале приключений)",45329,null],[46738,"2026-06-14T22:56:59",36,"Кью подняла голову наверх и посмотрела на луну, затем медленно и послушно закрыла глаза\n(1... Я верю в чудо 2... Верю в чудо 3... Чудо... свершись!)\n\n- Алмеер...",45329,null],[46746,"2026-06-14T22:59:51",23,"*вы находитесь в...... бесконечно светлой комнате рядом с тобой твой волк *",45329,null],[46747,"2026-06-14T22:59:55",23,"тогда и мне секунду описать//",45329,null],[46800,"2026-06-14T23:13:49",23,"*Алмеер сижит в посередине нечего спиной к вам и смотрит на дерево которая выросла из ниоткуда *",45329,null],[46803,"2026-06-14T23:14:00",23,"на цикл//",46789,null],[46825,"2026-06-14T23:16:50",23,"*мир в котором вы сейчас абсолютно белы но не ослепляющей и кажется бесконечным и вокруг фигуры в золотом продолжает распространяется зеленые растения и ты начинаешь медленно исцеляются от всего и очищается*\n\n~здравствуй дитя лесов",45329,null],[46827,"2026-06-14T23:17:49",36,"Кью убедившись что волк рядом и жив подходит ближе, но держится на расстоянии, Приветсвую вас Алмеер... Что... Что здесь произошло?...\n\nСмотрит она на загадочное дерево",46800,null],[46842,"2026-06-14T23:19:59",23,"~\"здесь\" все те кто умер вне этого мира \n\n* раздаётся вокруг тебя все тем же голосом*",45329,null],[46855,"2026-06-14T23:22:44",23,"~давно у меня не было посетителей дитя лесов даже не знаю что и проведать \n\n*Ты замечаешь то что всё начало идти в обратном порядке мы начали немного молодеть совсем немного буквально на пару дней и дерево стало ростком не больше обычного цветочка*",45329,null],[46862,"2026-06-14T23:26:12",23,"~мир в котором вы все  попали не обычен как ты могла заметить веть он мой\n\n*он встаёт и из света создаётся трон после того как он на него сел появляется стол и он жестом приглашает их присесть *",45329,null],[46869,"2026-06-14T23:28:25",23,"*в моменте замечаешь что у божество нет рта по крайней мере ты его не замечаешь и видны из всего его тела только в глаза притягательные золотистые *",45329,null],[46880,"2026-06-14T23:30:17",36,"Кью вглядываясь в каждое его движение не сразу понимает что её пригласили, затем слегка кивает и робкими движениями садится за стол. Волк же с\nЗалез на стул и сидел внимательно слушая",45329,null],[46884,"2026-06-14T23:30:57",36,"//бля..\n Спать хочу пизда... Е",45329,null],[46896,"2026-06-14T23:32:34",23,"*изначально там не было стула стоит тебе представить как он сразу появляется*",45329,null],[46900,"2026-06-14T23:33:09",23,"~в этом месте мы на равных \n*опять голос около тебя*",45329,null],[46905,"2026-06-14T23:33:38",23,"~дитя лисов скажи чего желает твоё сердце",45329,null],[46914,"2026-06-14T23:35:29",23,"~возрождение своего вида? \n~сила способная повергнуть меня и остальных? \n~или нечто иное видел тебя к цели \n\n*все места начинаете изменяться под твои подсознательные мысли твой родной дом сейчас этот маленький стол со стульями из света находится у тебя дома*",45329,null],[46933,"2026-06-14T23:38:28",23,"*каждый миг без ответа тянется как будто вечность как будто между вами нарастает невидимые напряжение переживания и сознание контрастов то что на протяжении двух дней вы не видели ни одного солнечного света А тут так много *",45329,null],[46957,"2026-06-14T23:45:40",23,"если Дка появится до того как я лягу скину ещё русалку",45329,null],[46960,"2026-06-14T23:46:09",23,"@Professor_3M653",45329,null],[48740,"2026-06-15T07:07:12",36,"//ебат....  Вкусна",46954,null],[48741,"2026-06-15T07:43:43",23,"пропустила другую вкусняшку",48740,null],[48742,"2026-06-15T08:01:05",36,"//я предупредила, что спать хочу",48741,null],[48744,"2026-06-15T08:03:08",36,"Хз равносильно ли это//",46954,null],[48745,"2026-06-15T08:10:25",36,"- Возрождение? Сама справилюсь...\n\nКью посмотрела в сторону волка\n\n- Мы же грибы... Чувствуем друг-друга и почти непобедимы... Ну и ещё как кролики размножаемся \n\nОна посмотрела на Алмеера с милой улыбкой\n\nЗатем убрала её и вновь серьезно и задумавшись посмотрела на него\n\n- Цель... Цели у меня нету... Или... Есть...\n\nОна посмотрела на потолок\n\n- Я не знаю... \n\nОна положила руку на грудь и сжала часть себя\n\n- У меня... Словно пусто... Вырвали что-то, что я должна знать... \n\nКью затем посмотрела на Алеена\n\n- Поэтому я не знаю какая у меня может быть цель...\n\nЛегла на стол прижавшись щекой к столу и стала пальцем водить по столу\n\n- А сила... Она нужна всем... В основном чтобы добиться своей цели, так что наверное всё таки сила... Таким слабым, хрупким и маленьким существам как я не выжить в этом мире без силы, кто угодно может просто подойти ко мне и например сжечь. Не смотря на то что я тоже живая, тоже хочу жить, веселится, дружить... Сила... Это то слово что может дать тебе возможность обезопасить тех кто рядом с тобой... Тех, к кому ты привязался \n\nКью посмотрела на волка и мягко улыбнулась, словно щас расплачится, а после села ровно подняв голову и взглянув на Алмеера. \n\n- Я решила, я хочу силы. Дай её мне, прошу...",46914,null],[48746,"2026-06-15T09:17:06",23,"в любом случае вкуснее меня не найдётся",48742,null],[48747,"2026-06-15T09:18:30",23,"*Ну чуть было не сожрал в голосину всё пространство Просто намекая на это*",48745,null],[48748,"2026-06-15T09:22:16",23,"~Я спросил не чего ты хочешь А чего желает твоё сердце \n\n*он просто пальцем постучал по столу в ожидании в ответ*\n\n~сила - Это не ответ силы бывают разные чтобы покорять миры или защитить себя или близких \n\n*после небольшой тишины после того как он всё высушил*\n\n~ты хочешь сил чтобы защитить других? защитить себя? покорить всех? \n\n*у него всё ещё не торта и его голос расстаётся по всему мирозданию*",48745,null],[48749,"2026-06-15T09:23:26",23,"~знаешь чему я покровительству? \n\n*он ждёт ответа только на два вопроса ради чего хочешь силу и за что отвечает Алмеер *",45329,null],[48751,"2026-06-15T09:27:41",36,"- Я всегда говорю от чистого сердца, разум чуждо для меня, я хочу силы чтобы покорять, если ты покоришь всех, то другие не тронут своих\n\nПосле чего та замолкла на секунду осматривая Алмеера\n\n- Честно? Нет... Я не так уж много и богов видела",45329,null],[48752,"2026-06-15T10:29:11",23,"~Бог веселее праздничество весёлых путешествий и кровавых заруб небольшой контраст один из самых честных богов\n~не бывает веселье без риска как и приключений без крови\n *цитирует самого себя*",45329,null],[48753,"2026-06-15T10:29:34",23,"~Мне казалось то что это воплощение самое известное из моих",45329,null],[48754,"2026-06-15T10:31:44",23,"~силы чтобы покорять? буйная девица даже как-то странно видеть твоё истинное имя как дитя лесов \n\n*резко приходит осознание то что он обращался по истинному имени просто самым грубым способом переводил его на общий чтобы ты могла понимать*",45329,null],[48755,"2026-06-15T10:33:01",23,"~ладно ты взмолилась богу ради прошение силы? это меня даже не уточняешь какую именно это по своему огорчит \n\n*хлопает в ладоши из чего весь мир полностью стирается и остаётся кристально белым как был до этого и остаётся только трон стол и стульчик на котором ты сидела*\n\n~На что ты готова ради силы?",45329,null],[49798,"2026-06-16T01:19:01",23,"Даже вопрос переформулирую",45329,null],[52042,"2026-06-16T20:53:47",36,"- Я не знаю зачем попросила тебя от помощи, того требовал случай. Ты же мне щас дал три варианта, я выбрала и ты ещё меня судишь за мой выбор? Даже как то мелочно... особенно если учитывать что ты бог...\n\nОна смотрела на тебя с неким безразличием, затем легла на спинку стула расслабившись\n\n- Ладно, ладно... ПРости, понимаю, как всё это звучит со стороны, но у меня... Пусто... ПОнимаешь? Такое ощущение, что я потеряла что-то важное, ещё и называешь меня так... Словно я какая-то значимая фигура, словно нужна, требуюсь. А понять этого не могу... Но выбор свой не уберу, так считает моё сердце, разум может и говорит другое, но кому нужен здравый смысл?",48755,null],[52048,"2026-06-16T20:54:30",36,"Кью подняла голову и посмотрела в белую пустоту\n\n- На что готова? Да на всё... Я за любой движ, учитывая что вариантов то особо у меня и нет",45329,null],[52056,"2026-06-16T20:56:03",23,"подожди ты мне лень",45329,null],[52085,"2026-06-16T21:01:15",36,"//ок",45329,null],[52432,"2026-06-16T21:59:05",23,"~забей и начни новую жизнь \n \n*его руки ниоткуда появляется бокал какой-то красной жидкости у него всё ещё нет рота и он это просто выливает на место где должен быть рот и это поглощается*",52042,null],[52433,"2026-06-16T22:00:09",23,"~Ну знаешь среди этого ничего и всего одновременно становится скучно и хочется просто поболтать , прискорбно то что тебе это не интересно",45329,null],[52434,"2026-06-16T22:00:31",23,"*просто крутит бокал со стороны в сторону бокал начинает наполняться когда он делает небольшой оборот кистью*",45329,null],[52435,"2026-06-16T22:02:53",23,"@Professor_3M653 я и как бог и как мастер хочу просто посидеть поболтать поиграть повеселиться//",45329,null],[52437,"2026-06-16T22:08:09",36,"- Я не говорила что мне не интересно с тобой общаться, я просто не знаю о чём болтать. Типо.... У тебя есть занятные истории? Темы для разговора? Может слухи и мифы? На пустом месте завести диалог без цели сложно знаешь ли.... И ещё, а как ты этот.... \n\nКью показывает жест рукой что типо берёт бокал\n\n- Ну... Напиток...\n\nКью показывает что пьёт из бокала",52433,null],[52453,"2026-06-16T22:50:34",23,"бля",45329,null],[52454,"2026-06-16T22:50:38",23,"Только сейчас заметил",45329,null],[52457,"2026-06-16T22:54:27",23,"*мир буквально изменяется под твоим желанием и появляется бокал и наливается жидкостью в которую ты представила*\n\n~знаешь чем там мы даже похожи то что меняемся только есть отличие меняем меняют вера и возможно я когда-то потеряю себя хочешь увидеть силу господа которому собираешься поклоняться?",52437,null],[52458,"2026-06-16T23:12:52",36,"(а я разве собиралась?...) \n\n- Да давай, интересно же :3\n\nСказала Кью лёгким голосом словно у неё сквозняк в башке, паралельно с этим попивая напиток что у неё появился в руке словно это эталон искусства. Хотя был обычный вкусный фруктово-ягодно-цветочный фейский лимонадик",52457,null],[52459,"2026-06-16T23:28:27",23,"*пусть меняется по мере того как ты пьёшь и чего желаешь во время одного колодка он может стать как солёным так и сладким от самого дорогого вина что ты пробовала до мочи стоит тебе захотеть*\n\n~Смотри же внимательно, это лишь крошечное представление.\n\n*Пространство начинает вращаться. Оно бесконечно, но ваш стол остается неподвижным , для вашего глаза не за что зацепиться, но тебя всё равно клонит в тошноту от скорости. Пространство начинает искривляться, весь белый свет, окружающий вас, погружается в спираль и собирается в какой-то одной точке. Всё, кажется, сжали в одно место, оставшись в полной тьме, где видно только стол и вы. Там, где всё собиралось, появляется маленькая сфера, больше похожая на жвачку или попрыгунчик. После этого пространство окутывается новым ярким белым светом, когда к нему коснулся Алмеер, и это повторилось ещё раз... 12*.",52458,null],[52460,"2026-06-16T23:30:56",23,"*появляется 13 сфер которые божество беззаботна и не брежно просто жонглирует*\n~есть догадки что это?",45329,null],[52461,"2026-06-16T23:32:16",23,"*каждый из сфер светится по-разному и не надо слов чтобы понять что каждый из них наполнена разной силой не В смысле А количество А смысл её применения*",45329,null],[52462,"2026-06-16T23:32:16",36,"- Вау~ \n\nКью видит подобное впервые и искренне любуется от того что видит, услышав вопрос она не могла сразу отметить ведь была изумлена и ошеломлена.\n\n- Я... Не знаю... Миры? Планы? Желания?",45329,null],[52463,"2026-06-16T23:35:17",23,"*он кидает одну тебе который ты без труда неосознанно ловишь*\n\n~лучше это всё сразу это желание миллиарды существ молятся тебе ты слышишь каждую молитву как они восхваляют тебя как они дают тебе силу изменять миры и каждый из них отвечает за своё ту которую ты держишь в руках сферы жизни и она позволяет лечить любые недуги любые раны отталкивать существо любить всё живое в целом именно из-за этого они самая желанная и самая проклятая вещь \n\n*ты видишь то что каждый из сфер отталкивают друг друга как магниты но достаточно мощно  но алмир удерживает их попивая одной рукой какую-то красную жидкость из бокала*",45329,null],[52464,"2026-06-16T23:36:43",23,"*это немного взрывает разум твоего персонажи Бог даёт тебе в руки самое мощное что имеет буквальный источник своих сил*",45329,null],[52468,"2026-06-17T00:01:12",23,"@Professor_3M653",45329,null],[52476,"2026-06-17T01:01:55",23,"@Professor_3M653 слышишь ты вообще отвечать собираешься",45329,null],[52477,"2026-06-17T02:46:58",36,"- А....\n\nКью долго тупит пока не выдаёт самое глупое что она могла сказать в этот момент\n\n- А что будет... Что будет если его... СЪЕСТЬ?",52464,null],[52577,"2026-06-17T08:53:24",23,"~Ну ничего страшного просто хаотично начнёшь мутировать отрастишь пару конечностей включая изнутри думаю кровоток и прочее усилятся настолько то что превратишься в фонтан потому что кровь ускорится настолько то что будет пробивать артерии и умрешь жуткой смертью неспособности переварить и постоянно поглощаемой силы жизни просто лопнешь",45329,null],[52581,"2026-06-17T10:13:36",23,"*как только прикоснулась чувствуешь то что истощение от мяса единорога начинает исцеля ться практически мгновенно*\n\n~желание молитвы всё в этой сфере благодаря ней можно создать свой план свои миры но для этого нужны очень много последователей и знаешь что самое ужасное? то что каждый тянет к источнику своих сил каждый хочет чтобы ты соответствовал каким-то характеристикам Так что ты держишь в руке жаждет размножения и жизни защиты в любой жизни \n\n*как у него начинает кружиться как орбита остальные 12 сферы светящихся разным*\n\n~и представь каждый из них тянет в разном направлении каждый тебя подталкивает к чему-то Вот мои любимые \n\n*достаёт какой-то полностью тёмный в сферу который принятым светится немного фиолетовый из его полностью тёмного лица открывается виде рта*\n\n~я несу в мир откровения  сфера жизни всегда было у меня \n\n*ты впервые слышишь голос божества которые он сказал до этого он общался малой иллюзией он сказал это практически шёпотом Но это разнеслось эхом в твоей сознании когда ты заметил что сфера в твоих руках просто испанилась и оказалось у него в орбите*",52477,null],[72205,"2026-06-24T00:47:24",23,"Ну дашь б**** не знаю",45329,null],[72207,"2026-06-24T00:48:03",36,"//а... Пхыхыххы",72205,null],[72227,"2026-06-24T00:52:47",36,"Держа сферу и слушаю бога в голову Кью стали заполнять словно большой волной всякие грязные мысли, которые все приходили к одному... К силе и превосходстве над другими. Откуда эти мысли Кью не знала, но она и не боялась их, словно это было что то родное. Но вскоре сфера пропала из рук, словно песок... Кью слегка потеребинела руками словно щас уронит сферу из-за того что та резко пропала, а после посмотрела на бога.\n\n- То есть... С ней каждый может стать богом? Или эта сфера появляется в сердцах богов/полубогов?",52581,null],[72238,"2026-06-24T00:55:07",64,"//очень вовремя дма от сна отвлекаешь. Прости, мы его поебали и тебе ничегошеньки не осталось",72227,null],[72242,"2026-06-24T00:56:11",23,"эх",72238,null],[72257,"2026-06-24T01:00:58",23,"~каждый куёт её под себя Ну да ты права если её заиметь то можешь стать богом но каждый дар имеет свою цену сфера начинает изменять тебя под себя если она не создана тобой то ты приобретаешь черты владельца предыдущего настолько то что через пару лет от тебя ничего не останется ты это он в новом обличье ты ничего не помнишь о себе ничего не знаешь твои привычки меня за как и мировоззрение \n\n\n~сила тоже не бесплатная Вера людей подпитывает её и она изменчива когда-то придуманная людьми через пару лет становится вымыслом и вот ты из благородного Бога войны превращается в Бога подлости и скрытых атак",72227,null],[72283,"2026-06-24T01:05:04",23,"~неписаный закон бог не всемогущий порой смертные намного могущественнее бессмертных \n\n*вокруг него всё ещё крутится несколько шаров чем ближе тебя определённо из них тем разные мысли лезут тебе в голову от спасения всего живого до истребления*\n\n~и сама цель сферы она может отвергать твою суть если ты слишком Не похож под её требования ты либо меняешься под неё либо она не подчиняется тебе",45329,null],[72290,"2026-06-24T01:06:00",23,"~например сфера войны требуют чтобы ты хотел уничтожить мир и даёт тебе столько сил сколько у тебя последователей И сколько желаний у тебя в этом даже если последователь один Даже если он почти в тебя не верит если ты всем душой и телом всей божественной сути хочешь уничтожить мир у тебя будут это силы ужасное желание и ужасный пример Ну самый наглядный",45329,null],[72343,"2026-06-24T01:24:36",23,"ну пиздец я спать",45329,null],[72376,"2026-06-24T09:04:35",23,"ура я проснулся и не готов порвать хардп!",45329,null],[72377,"2026-06-24T10:55:09",36,"//когда инет есть тогда и отвлекаю, так что не буби мне тут",72238,null],[72380,"2026-06-24T11:04:55",36,"- То есть... Даже такая как я могу стать богом если будет желание?\n\nКью опустила голову задумавшись \n\n- Хм... У лёгкой силы есть цена, цена эта потеря личности. Свою же силу нужно упорно ковать пока рано или поздно ты не добьешься того чего так желал...\n\n(Сила... Почему... Почему мне кажется что я потеряла что-то? Что-то... Важное... Что определяет меня, меня. Как личность... Словно я существо из которого вытащили эту сферу)\n\nКью посмотрела на сферу с надеждой. Но вглядываясь в них не находила ни одной что подойдёт под её описание\n\n- Значит... Это бывшие боги?",72290,null],[72382,"2026-06-24T11:55:08",23,"ой бля про тебя забыл прости",45329,null],[72383,"2026-06-24T12:08:54",23,"~такие же как я полубоги будет правильнее верховный бог солнца которого вы все почитаете забрал все сферы из-за чего ни один смертный не может возвыситься включая меня \n\n*просто разлёгся на своём троне всё ещё попивая красную жидкость*\n\n~Ну очень долго объяснять Ну да если очень коротко говорить Да это бывшие боги \n\n~просто в понтоне божеств не рождаются в привычном понимании и не умирают тоже в привычном понимании по сути они бесконечно спят пока их не забудут или наоборот не вспомнят настолько чтобы их возродить \n\n*делает полный глоток бокал всё ещё сам с собой наполняется *\n\n~аххх тяжело конечно быть смотрителем всех этих даров поэтому приходится прибегать на несколько хитростей у меня уже своя сфера куётся четвёртое уже от этого всего хотя обычно в божеств всего три хе-хе\n(что ты нервный смешок от божества звучит ещё не рвнее)\n\n*просто вырастает ещё две руки которые хлопают и снова возвращается в тело*\n\n~Ну ладно у меня давно не было собеседника Вот и расплываюсь по темам прошу простить \n\n~ так вот наверное ты задаёшься вопросом почему я повторю один и тот же вопрос что тебе нужно понятное дело сила нужна каждому но для чего ты будешь использовать силы Вот что мне интересно \n\n~я уже говорил насколько это важно типа \n*и секунды не прошло как он просто поменял свой голос сначала на милую жрицу робкую очень приятно было потом снова заменил но уже на изрядно выпившего какого-то мужчины*\nЯ хочу Чтобы никто никогда не грустил значит моя главная сфера развлечений\nЯ хочу защитить всех значит моя сфера защита жизни \n\n*Зачем в твоей голове раздаётся эхом тот же самый вопрос в котором задавал до этого только в другой формулировке*\n- чего ты хочешь когда владеешь силой",72380,null],[72447,"2026-06-24T16:33:21",36,"Кью понимала что от неё хотят, но не знала как ответить. Ведь она сама не знает зачем ей \"сила\", что-то внутри неё шепчет, что ей нужна сила, сила поможет. В чем поможет? Зачем сила? Эти вопросы лежат в глубине бедной и немного робкой Кью. Она не может их забыть и не может на них ответить, но они манят её... Что заставляет просить Кью именно силу.\n\n- Я не знаю, я просто... Просто чувствую что она мне нужна, что-то внутри меня рвётся наружу, чтобы сказать что-то, что я забыла. Но я не могу... Не могу вспомнить... Это нечто сказало, что нужна сила. Нужна чтобы вспомнить... \n\nЕё голос с волнующегося и робкого стал уверенным в себе и гордым \n\n- Сила поможет мне вернуть себя! Когда я завладею силой я буду хотеть получить то что когда-то утратила... То без чего мне тяжело ходить по этому свету",72383,null],[72449,"2026-06-24T16:33:49",23,"только открыл тг вот и оно",45329,null],[72450,"2026-06-24T16:35:29",36,"//я отвечаю по возможности",72449,null],[72457,"2026-06-24T16:55:19",23,"~единственное что нравится я вижу в тебя себя когда-то пустую оболочку без целей пустую душу знаешь что самое замечательное в этой душе? \n\n*пошли небольшого ожидания ответа*\n\n~если она пустая значит её можно наполнить чем хочешь \n\n*он создаёт небольшую сферу хрустальную через которую видно приключения остальных игроков как они пробираются через дремучие леса их телепортируют на финальную битву каждый сражается в поте лица и шаги от смерти*\n\n~видишь каждый из них невероятно разные и один отдал всего себя чтобы остановить пророчество что когда-то видел другой готов на всё ради знаний и каждый из них разный и каждый из них чем-то интересен если ты пуста по три аросто сделай себе маску и забудь про всё остальное\n\n~ если ты не можешь пока что ответить чего ты желаешь я не буду заставлять но я скажу тебе свою истинное имя ведь на удивление мы похожи только ты цепляешься за прошлое а я решил её оставить Ну что ж это по-своему прекрасно а теперь \n\n*сферы начинаю от кружиться вокруг него каждый из них подчиняется ему но не полностью как будто они отвергают его но он всё равно заставляет их работать наделяя пространство разнообразной магии его слова стали пронзительные*\n\n~Я Бог надежды и безумия, веселья чьё имя стало синонимом негодяи и многоликого на йотунском лиас'амуфа позволишь мне быть путеводной звездой для не знающего в ночи \n\n (знание как будто проникают в твой разум и ты поняла что это значит кажется что-то на религиозной те кто молятся во тьме и просят внимания становится понятно то что он отвечает каждой молитве существа которые отчаянные этого хочет быть услышанным и сейчас делает тебя жрецом просто чтобы увидеть твою судьбу)\n\n*пространство между вами сжимается до такого то что стол от величественного королевского сжимается до обычного чтобы он мог протянуть тебе руку и он ждёт пока ты пожнёшь её*",72447,null],[81236,"2026-06-29T15:29:08",36,"Кью смотрела на него сначала с трепетом, но затем все больше уходила в себя. В итоге она собралась с духом и молча протянула богу руку, чтобы подать её. Ей явно понадобится помощь такого бога",72457,null],[81237,"2026-06-29T15:40:23",23,"*зевает пока ждал твоего ответа*",45329,null],[81240,"2026-06-29T17:21:51",36,"//и????",81237,null],[81254,"2026-06-29T18:11:25",23,"~О, эта сфера времени столь капризна что время тут не синхронизировано с твоим миром Не удивляйся если тут ты просидела часа в своём мире недели две \n\n*Сжимает твою руку с изяществом достойным короля, и в тот же миг тебя прошибает волна могущества, стекающая со всех сфер, питая твою душу, словно нектар богов. и тут же отпускает твою руку как и прекращает вливать в тебя силы* (+1000 опыта)\n\n~Пробуди же себя от этого сладкого сна, возвысь мой величие в своих песнях и покажи мне, как звучит финальный аккорд твоей истории, прежде чем ты исчезнешь в иллюзиях. Развлекайся же, пока ты жива, ведь скука — единственный грех, который я не прощу.\n\n*после чего просто телепортирует тебя щелчком обратно на твой дом прошло много времени  как ты была и в своём кармане находишь записку *\n\n*если захочешь встретиться со мной Просто пропой обращении ко мне под луной*",45329,null],[82305,"2026-06-30T00:47:00",36,"Держа эту бумажку Кью подняла взгляд в небо, прижимая её к груди \n\n- Чего... Чего же я хочу.... Чего ищу... Надеюсь я найду на это ответ...",81254,null],[84682,"2026-06-30T20:29:08",23,"конец наконец или потом продолжим по причине я неделю буду не доступен",45329,null]]);
